import{z as B,x as n,o as e,c as p,q as o,j as s,D as E,d as A,s as l,S as i,b as r}from"./chunks/framework.C8m1ZpeB.js";const O=JSON.parse('{"title":"PLA 与 ROM 作组合","description":"","frontmatter":{"title":"PLA 与 ROM 作组合","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pla-rom.md","filePath":"cs/pla-rom.md","lastUpdated":1791063341000}'),d={name:"cs/pla-rom.md"};function m(c,a,P,R,h,M){const t=n("Mermaid");return e(),p("div",null,[a[2]||(a[2]=o('<h1 id="pla-与-rom-作组合" tabindex="-1">PLA 与 ROM 作组合 <a class="header-anchor" href="#pla-与-rom-作组合" aria-label="Permalink to &quot;PLA 与 ROM 作组合&quot;">​</a></h1><div class="epigraph"><p>任意真值表不必化成最少门：ROM 按地址读出函数值，PLA 烧与项再或起来，都是组合，只是实现形态不同。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/comparator-circuit">比较器</a>把 eq / 有符号 / 无符号三种比较收成组合块。从<a href="/cs/cmos-inverter">反相器</a>到比较，主干一直在拼门。本课不重接线旗标，也不从 FPGA LUT 架构史另起。缺口是：有些函数（控制器、不规则译码）用两级<strong>可编程与-或</strong>或一张表更自然。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>规范 SOP 是与项的或。PLA：可编程与阵列生成乘积项，或阵列把项送到各输出。ROM：地址即输入，每个地址存输出字，功能是「完整真值表」。缺口不是新的布尔公理，而是承认组合逻辑有<strong>表驱动</strong>实现，后课微程序、控制 ROM 用同一直觉。</p><p>PLA 不必列出全部 \\(2^n\\) 最小项，只烧需要的积项。ROM 在输入变宽时指数爆炸，只适合输入少、输出不规则。</p><h3 id="rom-不是存储器课的「可写主存」" tabindex="-1">ROM 不是存储器课的「可写主存」 <a class="header-anchor" href="#rom-不是存储器课的「可写主存」" aria-label="Permalink to &quot;ROM 不是存储器课的「可写主存」&quot;">​</a></h3><p>这里的 ROM 是组合查表：地址变，数据在 \\(t_{pd}\\) 后稳，没有写口、没有刷新。后课<a href="/cs/memory-array-sram-dram">SRAM/DRAM 阵列</a>才是可写存储。把本课 ROM 当成 DRAM，时序单元会提前出场。</p><p><span class="marginnote">Harris 用 PLA 实现有限状态机的下一态与输出——那是时序课；本课先当纯组合。PROM/EEPROM 的浮栅是工艺，功能仍是表。</span></p><p><span class="marginnote">「SOP（积之和）」翻译过来就是：把每种让输出为 1 的输入组合各写成一个「与」条件（积项），再把这些条件「或」起来。像把「批准休假」写成「（病假 且 有证明）或（年假 且 提前申请）」——每个括号就是一条积项。</span></p><p><span class="marginnote">数字实例：输入 8 位时 ROM 要备 2^8=256 行；20 位就是约 100 万行。若给 32 位 opcode 的译码配 ROM，理论上要 2^32 行——天文数字。PLA 只烧实际出现的少数 opcode 模式，几十条积项往往就够。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>输入经缓冲与反相，进与平面；积项进或平面得输出。ROM：译码器点一行，位线给出预存比特。两者都有明确 \\(t_{pd}\\)，计入<a href="/cs/critical-path">关键路径</a>。</p>',13)),(e(),s(i,null,{default:E(()=>[l(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%B8%83%E5%B0%94%E5%87%BD%E6%95%B0%22%5D%20--%3E%20GATES%5B%22%E9%97%A8%E7%BD%91%20%2F%20%E6%A0%87%E5%87%86%E5%8D%95%E5%85%83%22%5D%0A%20%20F%20--%3E%20PLA%5B%22%E4%B8%8E%E9%A1%B9%E5%8A%A0%E6%88%96%E9%A1%B9%22%5D%0A%20%20F%20--%3E%20ROM%5B%22%E5%9C%B0%E5%9D%80%E6%9F%A5%E8%A1%A8%22%5D%0A%20%20ROM%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%9C%80%E8%A6%81%E8%AE%B0%E5%BF%86%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[A("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"比较器、ALU 用结构块更省。不规则控制（「这些 opcode 组合才置这一位」）用 ROM/PLA 更直。后课单周期控制器真值表可以落成 PLA 或 ROM，仍是组合 \\(y=f(\\mathrm{opcode})\\)。组合主干到此收束：功能可门可表；下一课开始状态。",-1)),a[5]||(a[5]=r("p",null,"同一个函数落成 PLA 或 ROM，两种「表」的行数和代价差在哪？",-1)),(e(),s(i,null,{default:E(()=>[l(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E5%87%BD%E6%95%B0%EF%BC%8C%E4%B8%A4%E7%A7%8D%E8%A1%A8%E7%9A%84%E8%A7%84%E6%A8%A1%E4%BB%8E%E5%93%AA%E6%9D%A5%EF%BC%9F%22%5D%20--%3E%20ROM%5B%22ROM%EF%BC%9A%E7%A9%B7%E4%B8%BE%E5%AE%8C%E6%95%B4%E7%9C%9F%E5%80%BC%E8%A1%A8%22%5D%0A%20%20Q%20--%3E%20PLA%5B%22PLA%EF%BC%9A%E5%8F%AA%E7%83%A7%E7%94%A8%E5%88%B0%E7%9A%84%E7%A7%AF%E9%A1%B9%22%5D%0A%20%20ROM%20--%3E%20R1%5B%22%E8%A1%8C%E6%95%B0%E5%9B%BA%E5%AE%9A%202%20%E7%9A%84%20n%20%E6%AC%A1%E6%96%B9%EF%BC%8C%E4%B8%80%E8%A1%8C%E4%B8%8D%E5%A4%9A%E4%B8%80%E8%A1%8C%E4%B8%8D%E5%B0%91%22%5D%0A%20%20PLA%20--%3E%20P1%5B%22%E8%A1%8C%E6%95%B0%E7%AD%89%E4%BA%8E%E5%8C%96%E7%AE%80%E5%90%8E%E7%A7%AF%E9%A1%B9%E6%95%B0%EF%BC%8C%E4%B8%8E%20n%20%E6%97%A0%E5%BF%85%E7%84%B6%E6%8C%87%E6%95%B0%E5%85%B3%E7%B3%BB%22%5D%0A%20%20R1%20--%3E%20C%5B%22%E6%8D%A2%E6%B3%95%EF%BC%9A%E6%B1%82%E5%85%A8%E6%B1%82%E6%95%B4%E9%BD%90%EF%BC%8C%E8%BF%98%E6%98%AF%E6%B1%82%E5%B0%8F%E6%B1%82%E5%A4%9F%E7%94%A8%22%5D%0A%20%20P1%20--%3E%20C%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">直觉类比：ROM 像一本把每道题答案都印好的习题册，题目编号就是地址；PLA 像一张只写少数几条判题规则的小抄。题目总数爆炸时抄规则划算，输出又多又不规则时翻册子反而省心。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 FPGA 的 LUT 与可重配置互连，那是另一封装。不把闪存文件系统当 ROM 组合。时序电路仍未出现。</p><p>后课默认：任意组合函数可用门网、PLA 或 ROM 实现；下一课锁存与触发器才有记忆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PLA 烧 SOP；ROM 存真值表；都是组合。</li><li>输入宽时 ROM 不划算；规则运算仍用加法器等结构块。</li><li>可写存储器是后课阵列，不是本课的 ROM。</li><li>出处：Harris and Harris。</li></ul>',6))])}const D=B(d,[["render",m]]);export{O as __pageData,D as default};
